import { expr, isCanonicalTsLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { DATAMINE_RESOURCE_TYPE } from "./module.js";
/** Emit table-owned datamines using the web client's V2 ownership model. */
export function tableDataminesToTf(datamines, opts) {
    const blocks = [];
    for (const [key, datamine] of Object.entries(datamines ?? {})) {
        if (!isCanonicalTsLabel(key)) {
            opts.diagnostics.push(`datamines key ${JSON.stringify(key)} is not a canonical tsLabel; dropped`);
            continue;
        }
        const primaryColumnNames = datamine.primaryColumns.flatMap((columnKey) => {
            const name = opts.columnNames[columnKey];
            if (name === undefined) {
                opts.diagnostics.push(`datamines.${key}.primaryColumns: unknown table column key ${JSON.stringify(columnKey)}; dropped`);
                return [];
            }
            return [name];
        });
        if (primaryColumnNames.length !== datamine.primaryColumns.length)
            continue;
        const attrs = {
            table_id: expr.resourceAttr("elementum_table", opts.tableTfLabel, ["id"]),
            name: datamine.name,
            primary_column_names: primaryColumnNames,
        };
        if (datamine.description !== undefined)
            attrs["description"] = datamine.description;
        if (datamine.filter !== undefined)
            attrs["filter"] = opts.filterToTf(datamine.filter);
        if (datamine.limit !== undefined)
            attrs["limit"] = datamine.limit;
        if (datamine.schedule?.kind === "fixed") {
            attrs["schedule_fixed"] = {
                time_unit: datamine.schedule.timeUnit,
                value: datamine.schedule.value,
                ...(datamine.schedule.description !== undefined && { description: datamine.schedule.description }),
            };
        }
        else if (datamine.schedule?.kind === "cron") {
            attrs["schedule_cron"] = {
                cron_expression: datamine.schedule.cronExpression,
                ...(datamine.schedule.description !== undefined && { description: datamine.schedule.description }),
            };
        }
        blocks.push({
            kind: "resource",
            type: DATAMINE_RESOURCE_TYPE,
            label: `${opts.tableTfLabel}_${tsLabelToTfLabel(key)}`,
            attrs,
        });
    }
    return blocks;
}
